 43	  orchestrator: ChatOrchestrator,
 44	  sessionStore?: SessionStore,
 45	  options: MessageHandlerOptions = {}
 46	) {
 47	  // Keyed by session, not socket: a resumed session can be open on more than one (specs/hal-engine-architecture/spec.md).
 48	  const lock = new PerSessionLock();
 49	  return function handleMessage(
 50	    ws: WebSocket,
 51	    session: ChatSession,
 52	    rawMessage: unknown,
 53	    signal?: AbortSignal
 54	  ): Promise<void> {
 55	    const validation = validateMessage(rawMessage);
 56	    // Queued with no await before it, so a session's user_messages, a failed one too, are answered in arrival order.
 57	    if (isUserMessageFrame(rawMessage)) {
 58	      return lock.run(session.sessionId, () =>
 59	        answerInTurn(ws, session, orchestrator, validation, signal, sessionStore)
 60	      );
 61	    }
 62	    // An async action runs up to its first await at once, so a ping is answered now and a throw stays a rejection.
 63	    return wsErrorHandler(ws, async () => answerFrame(ws, session, validation, sessionStore, options));
 64	  };
 65	}
