 67	// The whole answer, an error and the stream_end included, goes out inside the lock: an error frame names no message.
 68	async function answerInTurn(
 69	  ws: WebSocket,
 70	  session: ChatSession,
 71	  orchestrator: ChatOrchestrator,
 72	  validation: ValidationResult,
 73	  signal: AbortSignal | undefined,
 74	  sessionStore?: SessionStore,
 75	  options: MessageHandlerOptions = {}
 76	): Promise<void> {
 77	  // Its socket closed while it waited: nobody is left to read the answer, and a session's last close took its credentials.
 78	  if (signal?.aborted || ws.readyState === WebSocket.CLOSING || ws.readyState === WebSocket.CLOSED) {
 79	    log.info('message', 'queued message dropped: its socket closed', {sessionId: session.sessionId});
 80	    return;
 81	  }
 82	  const startedAt = Date.now();
 83	  try {
 84	    await wsErrorHandler(ws, () => answerUserMessage(ws, session, orchestrator, validation, signal, sessionStore));
 85	  } finally {
 86	    endTurn(ws, session, signal, startedAt);
 87	  }
 88	}
