 90	// A turn whose socket closed is abandoned rather than ended: nobody is left to read a terminal frame.
 91	function endTurn(ws: WebSocket, session: ChatSession, signal: AbortSignal | undefined, startedAt: number): void {
 92	  if (signal?.aborted) {
 93	    log.info('message', 'turn abandoned: its socket closed', {
 94	      sessionId: session.sessionId,
 95	      elapsedMs: Date.now() - startedAt,
 96	    });
 97	    return;
 98	  }
 99	  sendStreamEnd(ws);
100	}
